/** The movement envelope shared by the player, formations, and targeting. */
export const PLAYABLE_ENVELOPE = {
  minX: -7.2,
  maxX: 7.2,
  minY: -2.4,
  maxY: 4.7,
} as const

/**
 * One deterministic difficulty curve for the whole mission. Progress is the
 * distance travelled over the 420m route, clamped to [0, 1]. Every multiplier
 * has a cap so late waves are demanding without becoming unavoidable.
 */
export const LEVEL_LENGTH = 420

export interface Difficulty {
  progress: number
  healthMultiplier: number
  fireIntervalMultiplier: number
  projectileSpeed: number
  aimLead: number
  accuracy: number
  waveDensity: number
  formationScale: number
}

export function normalizedLevelProgress(distance: number) {
  return Math.min(1, Math.max(0, distance / LEVEL_LENGTH))
}

export function getDifficulty(progress: number): Difficulty {
  const p = Math.min(1, Math.max(0, progress))
  return {
    progress: p,
    healthMultiplier: 1 + p * 0.9,
    fireIntervalMultiplier: 1 - p * 0.45,
    projectileSpeed: 42 + p * 21,
    aimLead: 0.15 + p * 0.85,
    accuracy: 0.34 + p * 0.6,
    waveDensity: 1 + p * 0.5,
    formationScale: 1 + p * 0.22,
  }
}

export function scaledHealth(baseHealth: number, difficulty: Difficulty) {
  return Math.max(1, Math.ceil(baseHealth * difficulty.healthMultiplier))
}

export function clampToPlayableEnvelope(x: number, y: number) {
  return {
    x: Math.min(PLAYABLE_ENVELOPE.maxX, Math.max(PLAYABLE_ENVELOPE.minX, x)),
    y: Math.min(PLAYABLE_ENVELOPE.maxY, Math.max(PLAYABLE_ENVELOPE.minY, y)),
  }
}

export interface AimPoint {
  x: number
  y: number
  z: number
}

/**
 * Deterministic bounded intercept. Error is deliberately applied before the
 * final envelope clamp, so an inaccurate shot can never become unfairly
 * aimed outside the space the player can reach.
 */
/** Small deterministic hash with every character of an ID and the shot index. */
export function deterministicAimSeed(id: string, shotIndex: number) {
  let hash = 2166136261 >>> 0
  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index)
    hash = Math.imul(hash, 16777619) >>> 0
  }
  hash ^= shotIndex >>> 0
  hash = Math.imul(hash, 16777619) >>> 0
  return ((hash / 0xffffffff) * 2) - 1
}

/** Solve a quadratic intercept and cap it so shots never predict an old position. */
export function boundedInterceptTime(
  player: AimPoint,
  velocity: { x: number; y: number },
  origin: AimPoint,
  projectileSpeed: number,
  maxTime = 1.4,
) {
  const rx = player.x - origin.x
  const ry = player.y - origin.y
  const rz = player.z - origin.z
  const vx = velocity.x
  const vy = velocity.y
  const a = vx * vx + vy * vy - projectileSpeed * projectileSpeed
  const b = 2 * (rx * vx + ry * vy)
  const c = rx * rx + ry * ry + rz * rz
  let time = c > 0 ? Math.sqrt(c) / projectileSpeed : 0.15
  if (Math.abs(a) > 0.001) {
    const discriminant = b * b - 4 * a * c
    if (discriminant >= 0) {
      const root = Math.sqrt(discriminant)
      const first = (-b - root) / (2 * a)
      const second = (-b + root) / (2 * a)
      const candidates = [first, second].filter((candidate) => candidate > 0)
      if (candidates.length > 0) time = Math.min(...candidates)
    }
  }
  return Math.min(maxTime, Math.max(0.15, time))
}

export function predictAimTarget(
  player: AimPoint,
  velocity: { x: number; y: number },
  origin: AimPoint,
  difficulty: Difficulty,
  seed: number,
): { x: number; y: number } {
  const interceptTime = boundedInterceptTime(player, velocity, origin, difficulty.projectileSpeed)
  const lead = interceptTime * difficulty.aimLead
  const boundedSeed = Math.min(1, Math.max(-1, seed))
  const error = 1 - difficulty.accuracy
  return clampToPlayableEnvelope(
    player.x + velocity.x * lead + boundedSeed * 2.4 * error,
    player.y + velocity.y * lead - boundedSeed * 1.6 * error,
  )
}

/** Deterministic formation expansion and density: no random wave spawns. */
export function buildWave(
  enemies: Array<{ variant: 'scout' | 'heavy' | 'turret' | 'carrier'; x: number; y: number; z: number; health: number; target?: 'lyra' | 'rook' | 'pip' }>,
  difficulty: Difficulty,
) {
  const result = enemies.map((enemy) => {
    const position = clampToPlayableEnvelope(enemy.x * difficulty.formationScale, enemy.y)
    return {
      ...enemy,
      ...position,
      health: scaledHealth(enemy.health, difficulty),
      maxHealth: scaledHealth(enemy.health, difficulty),
    }
  })
  // Floor keeps the total count at or below the requested density. Ceil would
  // turn a three-enemy wave at the 1.5x cap into five enemies (1.67x).
  const extraCount = Math.max(0, Math.floor((difficulty.waveDensity - 1) * enemies.length))
  for (let index = 0; index < extraCount; index += 1) {
    const source = enemies[index % enemies.length]
    if (source.variant === 'carrier') continue
    const position = clampToPlayableEnvelope(
      source.x * difficulty.formationScale + (index % 2 === 0 ? -2.4 : 2.4),
      source.y + (index % 2 === 0 ? 0.8 : -0.8),
    )
    result.push({
      ...source,
      ...position,
      z: source.z - 7 - index * 3,
      health: scaledHealth(source.health, difficulty),
      maxHealth: scaledHealth(source.health, difficulty),
      target: undefined,
    })
  }
  return result
}

