/** Squared distance from a point to a swept segment. Pure and allocation-free. */
export function segmentPointDistanceSquared(
  start: { x: number; y: number; z: number },
  end: { x: number; y: number; z: number },
  point: { x: number; y: number; z: number },
) {
  const dx = end.x - start.x
  const dy = end.y - start.y
  const dz = end.z - start.z
  const lengthSquared = dx * dx + dy * dy + dz * dz
  const projection = lengthSquared > 0
    ? Math.min(1, Math.max(0, ((point.x - start.x) * dx + (point.y - start.y) * dy + (point.z - start.z) * dz) / lengthSquared))
    : 0
  const nearestX = start.x + dx * projection
  const nearestY = start.y + dy * projection
  const nearestZ = start.z + dz * projection
  const offsetX = point.x - nearestX
  const offsetY = point.y - nearestY
  const offsetZ = point.z - nearestZ
  return offsetX * offsetX + offsetY * offsetY + offsetZ * offsetZ
}

export function sweptCapsuleHits(
  start: { x: number; y: number; z: number },
  end: { x: number; y: number; z: number },
  point: { x: number; y: number; z: number },
  radius: number,
) {
  return segmentPointDistanceSquared(start, end, point) <= radius * radius
}

/**
 * Segment-vs-moving-point collision. The relative segment is the projectile
 * path minus the target's path, so a target moving between simulation frames
 * cannot make a fast laser tunnel through it.
 */
export function sweptMovingCapsuleHits(
  projectileStart: { x: number; y: number; z: number },
  projectileEnd: { x: number; y: number; z: number },
  targetStart: { x: number; y: number; z: number },
  targetEnd: { x: number; y: number; z: number },
  radius: number,
) {
  return segmentPointDistanceSquared(
    { x: projectileStart.x - targetStart.x, y: projectileStart.y - targetStart.y, z: projectileStart.z - targetStart.z },
    { x: projectileEnd.x - targetEnd.x, y: projectileEnd.y - targetEnd.y, z: projectileEnd.z - targetEnd.z },
    { x: 0, y: 0, z: 0 },
  ) <= radius * radius
}

